return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Arabic','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-03 14:31+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'ar','plural-forms'=>'nplurals=6; plural=n==0 ? 0 : n==1 ? 1 : n==2 ? 2 : n%100 >= 3 && n%100<=10 ? 3 : n%100 >= 11 && n%100<=99 ? 4 : 5;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['"%1$s %2$s" saved.'=>'تم حفظ "%1$s %2$s".','"%1$s" created. %2$d template updated.'=>'تم إنشاء "%1$s". تم تحديث %2$d قالب.' . "\0" . 'تم إنشاء "%1$s". تم تحديث %2$d قوالب.' . "\0" . '' . "\0" . '' . "\0" . '' . "\0" . '','"%s" created.'=>'تم إنشاء "%s".','%d language not yet linked'=>'لم يتم ربط %d لغة بعد' . "\0" . 'لم يتم ربط %d لغات بعد' . "\0" . '' . "\0" . '' . "\0" . '' . "\0" . '','%d link updated.'=>'تم تحديث %d رابط.' . "\0" . 'تم تحديث %d روابط.' . "\0" . '' . "\0" . '' . "\0" . '' . "\0" . '','%d locale pack installed.'=>'تم تثبيت حزمة لغة واحدة (%d).' . "\0" . 'تم تثبيت حزم لغوية (%d).' . "\0" . '' . "\0" . '' . "\0" . '' . "\0" . '','%d navigation reference updated.'=>'تم تحديث مرجع تنقل %d.' . "\0" . 'تم تحديث مراجع التنقل %d.' . "\0" . '' . "\0" . '' . "\0" . '' . "\0" . '','%d part reference updated.'=>'تم تحديث مرجع جزء %d.' . "\0" . 'تم تحديث مراجع الأجزاء %d.' . "\0" . '' . "\0" . '' . "\0" . '' . "\0" . '','%s Archive'=>'%s الأرشيف','(avg %.1f hits/block)'=>'(متوسط %.1f نقرات/كتلة)','(avg %.1f hits/entry)'=>'(متوسط %.1f ضربات/مدخل)','(disabled)'=>'معطل','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} لم يكن لديه روابط قابلة للاستبدال — أعد الفحص للتحقيق)','.txt file(s) in the directory'=>'.txt ملف(ات) في الدليل','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>لينغوا فورج:</strong> تم الاحتفاظ بـ %1$d قالبًا مترجمًا من سمة &#8220;%2$s&#8221; في قاعدة البيانات ولكنه غير نشط حاليًا. ستصبح نشطة مرة أخرى إذا قمت بإعادة تفعيل تلك السمة. لنقل ترجماتك إلى السمة الجديدة، أعد إنشائها عبر <strong>الإعدادات → لينغوا فورج → التوجيه → هيكل FSE</strong>.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> رابط قابل للإصلاح التلقائي','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> روابط بحاجة لمراجعة يدوية','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> مسار قديم','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> مشكلة في القالب','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'يقبل فقط ملفات .mo المجمعة. يجب أن يتبع اسم الملف النمط {textdomain}-{locale}.mo. استبدال ملف بنفس الاسم سيقوم بالاستبدال.','Action'=>'إجراء','Actions'=>'إجراءات','active'=>'نشط','Active Languages'=>'اللغات النشطة','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'اللغات النشطة: أضف كل لغة تريد دعمها. يحصل كل لغة على بادئة عنوان URL أو نطاق فرعي وعلامة hreflang في &lt;head&gt; الصفحة.','Active Provider'=>'مزود نشط','Add entry'=>'إضافة إدخال','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'أضف تعليمات لتحسين المسودة — مثلاً اجعله أقصر، أضف قسم خاتمة، استخدم سجل أكثر رسمية، أدرج قسم الأسئلة الشائعة…','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'أضف تعليمات لتحسين المسودة — مثلاً اجعلها أقصر، أضف قسم الخاتمة، استخدم سجلًا أكثر رسمية…','Add new entry'=>'إضافة إدخال جديد','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'أضف مصطلحًا واحدًا في كل سطر. كل من المصطلح المصدر والعرض المستهدف مطلوبان. يحدد زوج اللغة الوظائف التي ينطبق عليها القيد.','Adds a link to the home page so visitors can browse in their language.'=>'يضيف رابطًا إلى الصفحة الرئيسية حتى يتمكن الزوار من التصفح بلغتهم.','Administrators only (manage_options)'=>'المسؤولون فقط (إدارة_الخيارات)','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'بعد تغيير اللغة الأساسية، قم بتفريغ الروابط الدائمة (القسم أدناه) لتحديث توجيه URL.','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'بعد تغيير إعدادات هيكل URL (بادئة المسار ↔ النطاق الفرعي)، قم دائمًا بزيارة الإعدادات → روابط دائمة وانقر على حفظ التغييرات لتفريغ قواعد إعادة الكتابة.','AI Behaviour Preset'=>'إعداد سلوك الذكاء الاصطناعي','AI cache cleared. %d entry was removed.'=>'تم مسح ذاكرة التخزين المؤقت للذكاء الاصطناعي. تم إزالة %d إدخال.' . "\0" . 'تم مسح ذاكرة التخزين المؤقت للذكاء الاصطناعي. تم إزالة %d إدخالات.' . "\0" . '' . "\0" . '' . "\0" . '' . "\0" . '','AI Cache: lists cached AI responses with hit counts. Clear the whole cache or a single post\'s entries. Use "Clear" before testing a translation change — cached results are returned even when you change the AI preset or model until the cache entry is evicted.'=>'ذاكرة التخزين المؤقت للذكاء الاصطناعي: قائمة الاستجابات المخزنة مؤقتًا مع عدد الضربات. امسح الذاكرة المؤقتة بأكملها أو إدخالات منشور واحد. استخدم "مسح" قبل اختبار تغيير الترجمة — يتم إرجاع النتائج المخزنة مؤقتًا حتى يتم إخلاء إدخال الذاكرة المؤقتة عند تغيير إعدادات الذكاء الاصطناعي أو النموذج.','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'ميزات الذكاء الاصطناعي اختيارية. التوجيه اللغوي، hreflang، مفتاح التبديل اللغوي، ونظام مجموعة الترجمة كلها تعمل بدون مزود مكون.','AI Limits & Security'=>'حدود و أمان الذكاء الاصطناعي','AI provider returned an empty response.'=>'استجابة فارغة من مزود الذكاء الاصطناعي.','AI Usage'=>'استخدام الذكاء الاصطناعي','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'استهدف 120–160 حرفًا. اتركه فارغًا لاستخدام بديل المقتطف.','All time'=>'جميع الأوقات','Allow editors to lock individual blocks'=>'السماح للمحررين بقفل الكتل الفردية','Allow Gutenberg template-editing mode on post screens'=>'السماح بوضع تحرير النموذج في صفحات المنشور','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'احذف أيضًا تعيينات اللغة، علاقات الترجمة، الأوصاف التعريفية، القاموس، وذاكرة الترجمة عند إلغاء تثبيت الإضافة.','Also generate meta description'=>'أيضًا إنشاء وصف ميتا','Alternative (server-side):'=>'بديل (جانب الخادم):','An unknown error occurred.'=>'حدث خطأ غير معروف.','and'=>'و','Anthropic (Claude)'=>'أنثروبيك (كلود)','any'=>'أي','API calls saved by cache'=>'نداءات API محفوظة بواسطة الذاكرة المؤقتة','API Key'=>'مفتاح API','API Keys'=>'مفاتيح API','API Keys Tab'=>'علامة تبويب مفاتيح API','API Response Cache'=>'ذاكرة التخزين المؤقت لاستجابة API','Applied ✓'=>'مُطبَّق ✓','Apply failed — please try again.'=>'فشل التطبيق — يرجى المحاولة مرة أخرى.','Apply to Block'=>'تطبيق على الحاشية','Apply to Editor'=>'تطبيق على المحرر','Apply to Footnote'=>'تطبيق على الحاشية','Apply to Meta Description'=>'تطبيق على الوصف التعريفي','Apply translation'=>'تطبيق الترجمة','Applying…'=>'جارٍ التطبيق…','Approximate size'=>'الحجم التقريبي','Archive'=>'أرشيف','Archive: %s'=>'الأرشيف: %s','Authors and above (edit_published_posts)'=>'المؤلفون وما فوق (تحرير_نشر_المشاركات)','Behavior'=>'السلوك','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'السلوك: اختر إعداد الذكاء الاصطناعي (حرفي، متوازن، إبداعي)، أضف تعليمات مخصصة للموقع بأكمله، قم بتمكين أو تعطيل الترجمة التلقائية بعد الحفظ، وتهيئة ذاكرة الترجمة.','Block Content'=>'محتوى الكتلة','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'يعرض إشعارًا مؤدبًا عندما يتم عرض الصفحة الحالية بلغتها الأصلية لأنه لا توجد ترجمة للغة الزائر. يقوده إشارة LINGUAFORGE_LANG_FALLBACK_ACTIVE لموجه لينجوا فورج — لا يصدر شيئًا عندما توجد ترجمة للغة الطلب.','Block Editor'=>'محرر الكتلة','block keywordfallback'=>'البديل','block keywordi18n'=>'i18n','block keywordlanguage'=>'اللغة','block keywordlinguaforge'=>'لينجوا فورج','block keywordtranslation'=>'الترجمة','Block locking'=>'قفل الكتلة','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'أنماط الكتل المسجلة لأنواع المنشورات المخصصة. استخدم زر الترجمة لإنتاج نسخة بلغة أخرى. يتم حفظ المحتوى المترجم هنا ويمكن نسخه إلى أي منشور CPT من أداة إدراج الأنماط في محرر الكتل أو استخدامه كنقطة انطلاق لنمط متزامن (كتلة قابلة لإعادة الاستخدام).','block titleMissing Translation Notice'=>'إشعار الترجمة المفقودة','Block translation reuses'=>'إعادة استخدام ترجمات الكتل','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Configure in Settings → Behavior.'=>'ذاكرة تخزين مؤقت للترجمة على مستوى الكتلة مشتركة عبر المنشورات. عند التمكين، يتم تقديم الكتل المتطابقة (نفس العلامة، زوج اللغة، والقاموس) من الذاكرة بدلاً من استدعاء الذكاء الاصطناعي مرة أخرى. قم بالتهيئة في الإعدادات → السلوك.','Browser language redirect'=>'إعادة توجيه لغة المتصفح','Built-in preset instructions:'=>'تعليمات الإعداد المسبق المدمجة:','Bulletize (•-prefixed)'=>'قائمة نقطية (مُعلمة بـ •)','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'تخزين الترجمات المترجمة على مستوى الكتلة بحيث لا يدفع المحتوى القابل لإعادة الاستخدام (التذييلات المشتركة، الشريط الجانبي، الأكورديونات، الأقسام القانونية الثقيلة) مكالمة API في كل مرة. عند التفعيل، يقوم تدفق الترجمة بتحليل كل منشور إلى كتل، ويبحث في ذاكرة التخزين المؤقت عن كل كتلة، ويرسل فقط الكتل غير المخزنة إلى الذكاء الاصطناعي في طلب مجمع واحد. تعديلات القاموس وتغييرات إعدادات الامتثال تلغي تلقائيًا صلاحية الترجمات المخزنة المؤقتًا المتأثرة. عرض الإحصائيات ومسح ذاكرة التخزين المؤقت تحت الصيانة.','cached'=>'مخبأ','Cached API responses'=>'استجابات API المخزنة مؤقتًا','Cached block translations'=>'ترجمات الكتل المخزنة مؤقتًا','Cancel'=>'إلغاء','Cannot determine target language from slug.'=>'لا يمكن تحديد اللغة الهدف من الرابط المختصر.','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'تحديد مقدار استخدام الذكاء الاصطناعي الذي يمكن للموقع توليده وتقييد الأدوار التي يمكنها تشغيل مكالمات الذكاء الاصطناعي المدفوعة. يتوضع فوق حد المعدل لكل مستخدم (30 طلبًا / دقيقة، مبرمج بشكل ثابت) الذي يحمي بالفعل من حلقات الجري غير المحدودة لمستخدم واحد.','chars'=>'حروف','Chunk translated'=>'تمت ترجمة الجزء','Chunk translated to:'=>'تمت ترجمة الجزء:','Clear'=>'مسح','Clear All'=>'مسح الكل','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'هل تريد مسح جميع نتائج الذكاء الاصطناعي المخزنة مؤقتًا؟ ستؤدي الطلبات المستقبلية إلى استدعاءات API جديدة حتى يتم إعادة بناء الذاكرة المؤقتة.','Clear API Response Cache'=>'مسح ذاكرة التخزين المؤقت لاستجابة API','Clear Debug Files'=>'مسح ملفات التصحيح','Clear hints'=>'مسح التلميحات','Clear input'=>'مسح الإدخال','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'هل تريد مسح ذاكرة الترجمة بالكامل؟ ستقوم الترجمات المستقبلية بإعادة بناء الكاش أثناء تشغيلها.','Clear Translation Memory'=>'مسح ذاكرة الترجمة','Close'=>'إغلاق','Close language panel'=>'إغلاق لوحة اللغة','Close popover'=>'إغلاق النافذة المنبثقة','Compliance Preset'=>'إعدادات الامتثال','Content generated'=>'تم إنشاء المحتوى','Content Generator'=>'مولد المحتوى','Content ready'=>'المحتوى جاهز','Contributors and above — default (edit_posts)'=>'المساهمون وما فوق — الافتراضي (تحرير_المشاركات)','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'تحكم في مقدار المحتوى المرسل إلى الذكاء الاصطناعي ومدى حجم الاستجابة الممكن. اترك حقلًا فارغًا لاستخدام الافتراضي المدمج (المعروض كمحدد موضع). قم برفع هذه القيم إذا كانت الصفحات الكبيرة تُقطع؛ وخفضها لتقليل تكاليف API.','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'يتحكم في ميزانية الرموز وحدود الإدخال لميزة مولد محتوى الذكاء الاصطناعي. اترك الحقول فارغة لاستخدام الإعدادات الافتراضية المدمجة.','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'يحدد ما يحدث عندما يقوم مسؤول بحذف الإضافة من الإضافات → الإضافات المثبتة → حذف. يتم دائمًا حذف إعدادات الإضافة وذاكرة التخزين المؤقت للذكاء الاصطناعي. يتم الاحتفاظ بتعيينات اللغة والعلاقات الترجمة بشكل افتراضي بحيث يمكن لمسح غير مقصود أو إعادة تثبيت أن يستأنف من حيث توقف.','Conversational'=>'محادثة','Copied ✓'=>'تم النسخ ✓','Copy'=>'نسخ','Copy markup'=>'نسخ التعليمات البرمجية','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'انسخ النتيجة والصقها حيثما دعت الحاجة (مثلاً مباشرة في حقل الحاشية السفلية).','Copy to safe storage'=>'نسخ إلى التخزين الآمن','Could not add entry: source term and target term are required.'=>'تعذر إضافة الإدخال: يتطلب الأمر المصطلح المصدر والمصطلح الهدف.','Could not copy the file. Check that the uploads folder is writable.'=>'تعذر نسخ الملف. تحقق من أن مجلد التحميلات قابل للكتابة.','Could not instantiate the provider.'=>'تعذر إنشاء المزود.','Could not save the file. Check that the uploads folder is writable.'=>'تعذر حفظ الملف. تحقق من أن مجلد التحميلات قابل للكتابة.','Could not save the glossary entry.'=>'تعذر حفظ إدخال المصطلح.','CPT Block Patterns'=>'أنماط كتل CPT','Create'=>'إنشاء','Create missing'=>'إنشاء مفقود','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'إنشاء ترجمات لنوع المنشور "%s" يتطلب تكامل نشط. يرجى التأكد من تثبيت وتفعيل التكامل المطلوب.','Creating…'=>'جارٍ الإنشاء…','Creative / Marketing'=>'إبداعي / تسويقي','Creative / Marketing instructions'=>'تعليمات إبداعية / تسويقية','Current content (will be overwritten)'=>'المحتوى الحالي (سيتم استبداله)','Current title'=>'العنوان الحالي','Current: {current}'=>'الحالي: {current}','Currently inherited from the %s constant. Selecting a value here will override it.'=>'موروث حاليًا من الثابت %s. اختيار قيمة هنا سيقوم بتجاوزها.','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'حاليًا يتم تخطيها للمنشورات التي تستخدم عناصر نائب عن طريق تعليق الكتلة (حقول wp:details الملخص، إلخ) — فهي تمر إلى مسار الترجمة ذو الطلب الواحد الموجود.','Currently:'=>'حاليًا:','Custom'=>'مخصص','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'تم الوصول إلى الحصة اليومية للذكاء الاصطناعي (%1$d طلبات). تتجدد في %2$s بالتوقيت العالمي المنسق.','Daily request limit'=>'حد الطلب اليومي','Debug Files'=>'ملفات التصحيح','Debug files cleared. %d file was removed.'=>'تم مسح ملفات التصحيح. تم حذف ملف واحد.' . "\0" . 'تم مسح ملفات التصحيح. تم حذف %d ملفات.' . "\0" . '' . "\0" . '' . "\0" . '' . "\0" . '','Debug logging'=>'تسجيل التصحيح','Debug logging disabled.'=>'تم تعطيل تسجيل التصحيح.','Debug logging enabled.'=>'تم تفعيل تسجيل التصحيح.','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'تصحيح: تمكين سجل التصحيح لالتقاط مطالبات الذكاء الاصطناعي واستجابات API في ملف محلي. تعطيل بعد استكشاف الأخطاء وإصلاحها — يكتب وضع التصحيح ملفًا في كل طلب للذكاء الاصطناعي.','Delete'=>'حذف','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'هل تريد حذف جميع ملفات .txt في دليل التصحيح؟ سيظل الدليل نفسه موجودًا حتى تستمر عمليات التصحيح المستقبلية في الوصول إليه بشكل نظيف.','Delete all files for this override (both .mo and .po)?'=>'هل تريد حذف جميع الملفات لهذا التجاوز (ملفات .mo و .po)؟','Delete content data on uninstall'=>'حذف بيانات المحتوى عند إلغاء التثبيت','Delete this glossary entry?'=>'هل تريد حذف إدخال المصطلح هذا؟','Describe what to write — topic, key points, structure…'=>'صف ما تريد كتابته — الموضوع، النقاط الرئيسية، الهيكل…','Directory'=>'الدليل','Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them. Increasing API spend immediately on busy sites is expected when disabled.'=>'تعطيل أثناء ضبط المطالبات أو عندما تحتاج إلى وصول كل طلب إلى مزود الذكاء الاصطناعي. لا يحذف التعطيل الإدخالات المخزنة مؤقتًا — استعادتها عند إعادة التمكين. من المتوقع أن يزيد الإنفاق على API على الفور على المواقع المشغولة عند تعطيله.','Display'=>'عرض','Displays the Lingua Forge language switcher.'=>'يعرض مبدل لغة لينغوا فورج.','Documentation'=>'توثيق','Done'=>'تم','Done — {done} of {total} post(s) fixed.'=>'تم — تم إصلاح {done} من {total} منشور.','Down'=>'أسفل','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'قم بتنزيل وتثبيت حزمة لغة ووردبريس الأساسية مباشرة من WordPress.org. بمجرد التثبيت، تصبح اللغة متاحة لتوجيه URL وسير عمل الترجمة بالذكاء الاصطناعي. يتم جلب قائمة اللغات المتاحة عند الطلب — انقر على الزر أدناه لتحميلها.','Dropdown direction'=>'اتجاه القائمة المنسدلة','Editors and above (edit_others_posts)'=>'المحررون وما فوق (تحرير_مشاركات_الآخرين)','Enable API response caching'=>'تمكين التخزين المؤقت لاستجابة API','Enable block-level translation cache reuse across posts'=>'تمكين إعادة استخدام ذاكرة التخزين المؤقت للترجمة على مستوى الكتلة عبر المنشورات','Enter your API key for at least one AI provider. Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'أدخل مفتاح API الخاص بك لواحد على الأقل من مزودي الذكاء الاصطناعي. يتم تشفير المفاتيح عند الراحة باستخدام AES-256-GCM مع سر خاص بالموقع (LINGUAFORGE_SECRET). لا تشارك تصديرات قاعدة البيانات بدون تدوير السر أولاً.','environment variable'=>'متغير البيئة','Error'=>'خطأ','Expand'=>'وسّع','Expected: {expected}'=>'متوقع: {expected}','Extra guidance — tone, style, constraints, target audience…'=>'إرشادات إضافية — النغمة، الأسلوب، القيود، الجمهور المستهدف…','Extra guidance — tone, style, constraints…'=>'إرشادات إضافية — النغمة، الأسلوب، القيود…','Failed. Please try again.'=>'فشل. يرجى المحاولة مرة أخرى.','Feature'=>'الميزة','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'يتم تصنيف الميزات إلى مستويين. أدخل معرف النموذج الدقيق لكل مستوى ومزود. اترك حقلًا فارغًا لاستخدام الإعداد الافتراضي المدمج (المعروض كعنصر نائب). يتم استدعاء نماذج المزود النشط فقط عند التشغيل — قم بتكوين الآخرين مسبقًا إذا كنت تخطط للتبديل.','File copied to safe storage successfully.'=>'تم نسخ الملف إلى التخزين الآمن بنجاح.','Files'=>'الملفات','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'تصل الملفات إلى الدليل أدناه. مفيد لتشخيص مشكلات الترجمة — قم بإيقاف التشغيل بمجرد أن تحصل على ما تحتاجه حتى لا تتراكم الملفات. يمكنك أيضًا فرض ذلك من wp-config.php باستخدام `define( \'LINGUAFORGE_AI_DEBUG\', true );` الذي يتجاوز التبديل.','Filter'=>'تصفية','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'مرر مع linguaforge_debug_dir لإعادة توجيه مخرجات التصحيح إلى موقع غير عام.','Fix'=>'إصلاح','Fix All'=>'إصلاح الكل','Fix all links'=>'تصحيح جميع الروابط','Fix all parts'=>'تصحيح جميع الأجزاء','Fix Links'=>'تصحيح الروابط','Fix Nav'=>'تصحيح التنقل','Fix Parts'=>'تصحيح الأجزاء','Fix Template'=>'إصلاح القالب','Fixing {n} / {total}…'=>'جارٍ إصلاح {n} / {total}…','Fixing…'=>'جارٍ الإصلاح…','Flush Permalink Rules'=>'مسح قواعد الرابط الثابت','Flush Permalinks'=>'مسح الروابط الثابتة','Footnote Content'=>'محتوى الحاشية','footnote(s) translated — applied together with content.'=>'تمت ترجمة الحاشية السفلية — تم تطبيقها مع المحتوى.','Footnotes'=>'الحواشي السفلية','Footnotes payload (advanced)'=>'حمولة الحواشي السفلية (متقدم)','Forbidden'=>'ممنوع','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'مُجبر على الإيقاف من قبل الثابت LINGUAFORGE_AI_DEBUG في wp-config.php. احذف تلك السطر للتحكم في هذا التبديل من هنا.','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'مُجبر على التشغيل من قبل الثابت LINGUAFORGE_AI_DEBUG في wp-config.php. احذف تلك السطر للتحكم في هذا التبديل من هنا.','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'تم العثور على {parts} عبر <strong>{total}</strong> من منشورات و صفحات <strong>{scanned}</strong> التي تم فحصها للغة <strong>{lang}</strong>.','From'=>'من','Front Page'=>'الصفحة الرئيسية','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'توطين FSE: إنشاء، ترجمة، وإصلاح الروابط في قوالب وتجزئة قوالب التعديل الكامل للموقع مباشرة من علامة التبويب هذه.','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'تم زرع قوالب FSE من السمة النشطة. أنشئها ثم قم بتخصيصها في محرر الموقع.','Full Article'=>'المقال الكامل','Full post'=>'المقال كامل','General'=>'عام','Generate'=>'إنشاء','Generate Content'=>'إنشاء المحتوى','Generate content…'=>'إنشاء المحتوى…','Generate Excerpt'=>'إنشاء مقتطف','Generate Meta Description'=>'إنشاء وصف ميتا','Generated Content'=>'المحتوى المولد','Generated meta description'=>'وصف ميتا مولد','Generating…'=>'جارٍ التوليد…','Generation failed.'=>'فشل التوليد.','Getting started'=>'البدء','Global AI preset'=>'إعدادات الذكاء الاصطناعي العالمية','Global default (%s)'=>'الإعداد الافتراضي العالمي (%s)','Glossary'=>'القاموس','Glossary entry added.'=>'تمت إضافة إدخال المصطلح.','Glossary entry removed.'=>'تمت إزالة إدخال المصطلح.','Glossary Tab'=>'علامة تبويب القاموس','Google (Gemini)'=>'جوجل (جميني)','Hide'=>'إخفاء','Hints'=>'تلميحات','Home link text'=>'نص رابط الصفحة الرئيسية','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'كيف يجب أن تظهر في الترجمة. اكتب نفس قيمة المصطلح المصدر لتوجيه الذكاء الاصطناعي للحفاظ عليه حرفيًا.','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','https://lingua-forge.com'=>'https://lingua-forge.com','Icon + label'=>'رمز + تسمية','Icon only'=>'رمز فقط','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'إذا تم تحديده، فإن إلغاء تثبيت الإضافة سيحذف بشكل دائم جميع تعيينات اللغة، علاقات الترجمة، الأوصاف التعريفية، الإعدادات المسبقة للصفحات، قاموس الذكاء الاصطناعي، وذاكرة الترجمة لكل منشور على هذا الموقع. لا يمكن التراجع عن ذلك. اتركه غير محدد إلا إذا كنت تزيل دعم التعددية اللغوية من الموقع بالكامل.','Improve writing'=>'تحسين الكتابة','Informative'=>'معلوماتي','Input tokens'=>'رموز الإدخال','Install'=>'تثبيت','Install a Language'=>'تثبيت لغة','Installing…'=>'جارٍ التثبيت…','Instructions (optional)'=>'تعليمات (اختياري)','Instructions / key points'=>'تعليمات / النقاط الرئيسية','Integration API'=>'واجهة برمجة التطبيقات للتكامل','Internal Link Fixer'=>'مصلح الروابط الداخلية','Introduction only'=>'مقدمة فقط','Invalid file reference.'=>'مرجع ملف غير صالح.','Invalid filename.'=>'اسم ملف غير صالح.','Invalid language.'=>'اللغة غير صالحة.','Invalid locale code.'=>'رمز اللغة غير صالح.','Invalid or primary language.'=>'اللغة غير صالحة أو أساسية.','Invalid post type.'=>'نوع المنشور غير صالح.','Invalid template part.'=>'جزء القالب غير صالح.','Invalid template type.'=>'نوع القالب غير صالح.','Key points, ideas, or structure to build from…'=>'نقاط رئيسية، أفكار، أو هيكل للبناء عليه…','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'يتم تشفير المفاتيح باستخدام AES-256-CBC قبل تخزينها في قاعدة بيانات ووردبريس. يتم اشتقاق سر التشفير من ملح المصادقة الخاص بك في ووردبريس (wp-config.php)، لذلك المفاتيح النصية العادية لا تلمس قاعدة البيانات.','Language'=>'اللغة','Language %s installed successfully.'=>'تم تثبيت لغة %s بنجاح.','Language (optional)'=>'اللغة (اختياري)','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'تم تعطيل تثبيت اللغة على هذا الخادم (تم تعيين DISALLOW_FILE_MODS).','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'تم تعطيل تثبيت اللغة على هذا الخادم. تم تعيين الثابت DISALLOW_FILE_MODS في wp-config.php. قم بتثبيت حزم اللغات يدويًا عبر WP-CLI: wp language core install de_DE','Language label'=>'علامة اللغة','Language Overrides'=>'تجاوزات اللغة','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'تجاوزات اللغة: إدارة ملفات تجاوز .po/.mo المخصصة لنصوص واجهة مستخدم Lingua Forge. استخدم هذا بدلاً من تحرير ملفات الإضافة مباشرة — تظل التجاوزات بعد التحديثات.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'فشل تثبيت حزمة اللغة. قد تكون اللغة مثبتة بالفعل، أو قد يكون رمز اللغة غير صحيح، أو قد يمنع الخادم كتابة الملفات.','Language Setup'=>'إعداد اللغة','Language Switcher'=>'مبدل اللغة','Language switcher'=>'مفتاح التبديل اللغوي','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'نسخ خاصة باللغة من أجزاء قالب السمة. بمجرد إنشائها، يتم تحديث القوالب للإشارة إلى الجزء الخاص باللغة.','Language:'=>'اللغة:','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'اللغات المعروفة حاليًا للموجه (مشتقة من حزم اللغة المثبتة في ووردبريس بالإضافة إلى اللغة الأساسية). قم بتثبيت حزم لغوية إضافية في القسم أدناه لجعل المزيد من اللغات متاحة للتوجيه والترجمة.','Last 30 days'=>'آخر 30 يومًا','Last 7 days'=>'آخر 7 أيام','Lead paragraph (≤60 w)'=>'الفقرة الافتتاحية (≤60 كلمة)','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'اترك حقل النموذج فارغًا لاستخدام النموذج الافتراضي المدمج لهذا المستوى. يظهر نص العنصر النائب النموذج الذي سيتم استخدامه.','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'اتركه فارغًا لأسماء العلامات التجارية والمصطلحات غير المرتبطة باللغة والتي يجب تطبيقها بغض النظر عن اللغة التي نترجم منها.','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'اتركه فارغًا لتطبيق هذا الإدخال على جميع اللغات الهدف — مثالي لأسماء العلامات التجارية، الاختصارات، والمصطلحات التي يجب أن تُحفظ حرفيًا في كل ترجمة.','Leave blank to keep the existing key. Enter a new value to replace it.'=>'اتركه فارغًا للحفاظ على المفتاح الحالي. أدخل قيمة جديدة لاستبداله.','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'اتركه فارغًا لاستخدام الإعداد الافتراضي المدمج. استعادة تجاوز محفوظ يعيد التعيين إلى الافتراضي عند الحفظ التالي.','Legal / Compliance'=>'قانوني / امتثال','Legal / Compliance instructions'=>'تعليمات قانونية / امتثال','Light'=>'خفيف','Light (default — fast and cost-effective)'=>'خفيف (افتراضي — سريع وفعال من حيث التكلفة)','Light (fast and cost-effective — Haiku / Flash)'=>'خفيف (سريع وفعال من حيث التكلفة — Haiku / Flash)','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'خفيف: يستخدم لوصف الميتا وتوليد المقتطفات — سريع، منخفض التكلفة.','Limit results to pages in the given Lingua Forge language code.'=>'تحديد النتائج لصفحات ضمن رمز لغة لينغوا فورج المحدد.','Limits'=>'الحدود','Lingua Forge'=>'لينجوا فورج','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'يضيف Lingua Forge التوجيه متعدد اللغات، الترجمة المدعومة بالذكاء الاصطناعي، علامات SEO hreflang، ومفتاح التبديل اللغوي إلى موقع WordPress الخاص بك.','Lingua Forge AI Tools'=>'أدوات لينجوا فورج للذكاء الاصطناعي','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'يقيد Lingua Forge ميزتين من Gutenberg بشكل افتراضي للحفاظ على اتساق السلوك التحريري عبر اللغات. اختر هنا عندما تحتاج إلى قدرات كاملة لـ Gutenberg / FSE.','Lingua Forge Settings'=>'إعدادات Lingua Forge','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'يستخدم Lingua Forge طبقتين مستقلتين من التخزين المؤقت لتجنب استدعاءات API المكررة للذكاء الاصطناعي. استخدم علامات التبويب أدناه لفحص وإدارة كل واحدة.','Lingua Forge uses two model tiers per provider:'=>'يستخدم Lingua Forge مستويين من النماذج لكل مزود:','Lingua Forge — Quick Translate'=>'لينجوا فورج — الترجمة السريعة','Lingua Forge — Settings'=>'لينغا فورج — الإعدادات','link(s)'=>'رابط(روابط)','Links'=>'روابط','Load available languages'=>'تحميل اللغات المتاحة','Loading…'=>'جارٍ التحميل…','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'يخزن Loco Translate ترجماته المخصصة في wp-content/languages/loco/ — وهو موقع يمكن أن يتم مسحه بصمت بواسطة تحديث نواة ووردبريس، إعادة تثبيت الإضافة، أو إذا تمت إزالة Loco Translate نفسه. نسخ الملفات هنا ينقلها إلى دليل Lingua Forge i18n-overrides، الذي يستمر خلال جميع تلك الأحداث ويُحمّل تلقائيًا في كل طلب.','Loco Translate — Copy to Safe Storage'=>'Loco Translate — النسخ إلى التخزين الآمن','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'أدنى قدرة في ووردبريس مسموح بها لتفعيل ميزات الذكاء الاصطناعي. تضييق هذا على مواقع متعددة المؤلفين يمنع المساهمين أو الحسابات التجريبية من تشغيل مكالمات الذكاء الاصطناعي المدفوعة. تجاوز حسب الميزة عبر مرشح `linguaforge_required_capability`.','Maintenance'=>'الصيانة','Maintenance Tab'=>'علامة التبويب الصيانة','Make casual'=>'اجعله غير رسمي','Make concise'=>'اجعله موجزًا','Make formal'=>'اجعله رسميًا','Mark citations needed'=>'علامة على الحاجة إلى اقتباسات','Max context characters'=>'أقصى عدد أحرف للسياق','Max hints characters'=>'أقصى عدد أحرف للتلميحات','Max input characters'=>'عدد الأحرف المدخلة القصوى','Max output tokens'=>'الحد الأقصى لعدد الرموز الناتجة','Maximum characters accepted from the input field. Default: 8 000.'=>'الحد الأقصى لعدد الأحرف المقبولة من حقل الإدخال. الافتراضي: 8000.','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'الحد الأقصى لعدد الأحرف لمحتوى المنشور الموجود الممرر إلى الذكاء الاصطناعي كالسياق البذري عند عدم تقديم تلميحات. الافتراضي: 6000.','Maximum characters read from the Hints field. Default: 2 000.'=>'الحد الأقصى لعدد الأحرف المقروءة من حقل التلميحات. الافتراضي: 2000.','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'الحد الأقصى لعدد الأحرف لمحتوى المنشور الموجه إلى الذكاء الاصطناعي. 0 يعني عدم وجود حد — يتم دائمًا إرسال المحتوى الكامل (موصى به). اضبط قيمة غير صفرية فقط إذا كان مزود الخدمة الخاص بك لديه نافذة سياق ضيقة. يتم كتابة تحذير في سجل أخطاء PHP كلما تم تقليم المحتوى.','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'الحد الأقصى لعدد الرموز التي يمكن للذكاء الاصطناعي إنتاجها في استجابة ترجمة واحدة. إذا تم قطع الترجمة بصمت في النهاية، قم بزيادة هذه القيمة. الافتراضي: 16000.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'الحد الأقصى للرموز التي قد ينتجها الذكاء الاصطناعي لكل عملية توليد. زد هذا إذا تم قطع المقالات الكاملة. الافتراضي: 8192.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'الحد الأقصى للرموز التي قد ينتجها الذكاء الاصطناعي لكل ترجمة سريعة. الافتراضي: 2000.','Meta Description'=>'وصف ميتا','Meta Description, Excerpt Generator'=>'وصف ميتا، مولد المقتطفات','Minimum role'=>'الدور الأدنى','Missing pattern name or language.'=>'اسم النمط أو اللغة مفقود.','Mode'=>'الوضع','Model'=>'النموذج','Model tier'=>'طبقة النموذج','Models'=>'نماذج','Models Tab (General)'=>'علامة التبويب النماذج (عام)','Most recent cached block'=>'الكتلة المخزنة مؤخرًا','Most recent cached response'=>'الاستجابة المخزنة مؤخرًا','Multilingual routing, SEO meta tags, and AI content tools for WordPress. Combines language detection, URL routing, hreflang, meta descriptions, and AI-powered excerpt, meta, and translation features.'=>'التوجيه متعدد اللغات، علامات وصف SEO، وأدوات المحتوى بالذكاء الاصطناعي لووردبريس. يجمع بين اكتشاف اللغة، توجيه URL، hreflang، أوصاف الميتا، وميزات المقتطفات، الميتا، والترجمة المدعومة بالذكاء الاصطناعي.','Name displayed in this language. Leave empty to use the source name.'=>'الاسم المعروض بهذه اللغة. اتركه فارغًا لاستخدام الاسم المصدر.','Navigation'=>'التنقل','Navigation has no content to translate.'=>'لا يوجد محتوى للتنقل لترجمته.','Navigation not found.'=>'لم يتم العثور على التنقل.','Navigation posts are translated via the Router tab, not this button.'=>'يتم ترجمة منشورات التنقل عبر علامة التبويب Router، وليس هذا الزر.','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'يتطلب ترجمة التنقل وجود مزود ذكاء اصطناعي نشط. قم بتكوين مفتاح API في علامة تبويب مفاتيح API.','Navigations'=>'التنقلات','Network error — could not reach the WordPress AJAX endpoint.'=>'خطأ في الشبكة — تعذر الوصول إلى نقطة نهاية WordPress AJAX.','No %s version found in this translation group.'=>'لم يتم العثور على إصدار %s في مجموعة الترجمات هذه.','No AI provider configured.'=>'مزود الذكاء الاصطناعي غير مهيأ.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'لم يتم تسجيل استخدام للذكاء الاصطناعي في النافذة المختارة (%s). اختر نطاقًا أوسع أعلاه.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'لم يتم تسجيل استخدام للذكاء الاصطناعي بعد. بمجرد أن يقوم محرر بتشغيل ترجمة، أو إنشاء وصف ميتا، أو استخدام أي ميزة أخرى للذكاء الاصطناعي، ستظهر الإجماليات هنا.','No API key configured for this provider.'=>'لا يوجد مفتاح API مهيأ لهذا المزود.','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'لا توجد تعليمات مدمجة — كل ميزة AI تستخدم إعداداتها الافتراضية الخاصة. املأ حقل تعليمات المطالب المخصصة أدناه لإضافة قواعد موقعك الخاصة.','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'لم يتم العثور على ملفات Loco Translate مخصصة بعد. تظهر هنا بمجرد حفظ ترجمة في Loco Translate.','No file was selected.'=>'لم يتم اختيار أي ملف.','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'لا تتطابق إدخالات المصطلح مع التصفية الحالية. قم بمسح التصفية لرؤية جميع الإدخالات، أو أضف إدخالًا جديدًا أدناه.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'لا توجد إدخالات مصطلح بعد. أضف واحدًا أدناه لبدء تطبيق المصطلحات في الترجمات.','No internal links found to update.'=>'لم يتم العثور على روابط داخلية للتحديث.','No language-specific template parts found to map.'=>'لم يتم العثور على أجزاء قالب محددة للغة لتعيينها.','No navigation references needed updating.'=>'لا حاجة لتحديث مراجع التنقل.','No override files uploaded yet.'=>'لم يتم تحميل ملفات تجاوز بعد.','No response from provider — check the error log for details.'=>'لا استجابة من المزود — تحقق من سجل الأخطاء للتفاصيل.','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'لم يتم تكوين لغات ثانوية. قم بتثبيت حزمة لغة أعلاه لتمكين إنشاء القوالب.','No source content found to translate.'=>'لم يتم العثور على محتوى مصدر لترجمته.','No source page linked yet.'=>'لم يتم ربط صفحة المصدر بعد.','No template part references needed updating.'=>'لا حاجة لتحديث مراجع أجزاء القالب.','No {lang} translation registered (TRID missing)'=>'لم يتم تسجيل ترجمة {lang} (TRID مفقود)','Notes'=>'ملاحظات','Notice message'=>'رسالة الإشعار','Notice settings'=>'إعدادات الإشعار','Oldest cached block'=>'الكتلة الأقدم المخزنة','Oldest cached response'=>'الاستجابة الأقدم المخزنة','Only .mo files are accepted.'=>'فقط ملفات .mo مقبولة.','OpenAI (GPT)'=>'OpenAI (GPT)','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'السياق الاختياري للمحررين (مثل "ASIC = الدائرة المتكاملة الخاصة بالتطبيق؛ الحفاظ عليها باللغة الإنجليزية في السياقات التقنية").','Output'=>'مخرجات','Output tokens'=>'رموز الإخراج','overridden'=>'تم تجاوزها','Override file deleted.'=>'تم حذف ملف التجاوز.','Override file uploaded successfully.'=>'تم تحميل ملف التجاوز بنجاح.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'يتجاوز إعداد الذكاء الاصطناعي للترجمة وتوليد المحتوى في هذه الصفحة. تستخدم جميع الميزات الأخرى دائمًا الإعداد الافتراضي العالمي.','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'يتجاوز إعداد الذكاء الاصطناعي للترجمة وتوليد المحتوى في هذه الصفحة. دائمًا ما يتم إلحاق تعليمات الموجه المخصصة على مستوى الموقع (الإعدادات → السلوك) بكل طلب بغض النظر عن هذا الاختيار.','Overview'=>'نظرة عامة','Page'=>'صفحة','Part'=>'جزء','Paste a footnote, sentence, or any snippet here…'=>'الصق حاشية، جملة، أو أي مقتطف هنا…','Paste text, or select text in the editor first…'=>'الصق النص، أو حدد النص في المحرر أولاً…','Paste text, or select text on the page first…'=>'الصق النص، أو حدد النص على الصفحة أولاً…','Paste your API key…'=>'الصق مفتاح API الخاص بك…','Path prefix — example.com/de/'=>'بادئة المسار — example.com/de/','Pattern'=>'نمط','Pattern has no content to translate.'=>'النمط لا يحتوي على محتوى للترجمة.','Pattern not found.'=>'لم يتم العثور على النمط.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'تم ترجمة النمط وحفظه. انسخ المحتوى إلى منشور CPT الخاص بك عبر أداة إدراج الأنماط في محرر الكتل أو استخدمه كنقطة انطلاق لكتلة قابلة لإعادة الاستخدام.','Pattern translation failed.'=>'فشلت ترجمة النمط.','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Always active — no separate toggle required. Entries are invalidated automatically when the content or AI provider/model changes. Use the toolbar "↺ Re-translate" button or click Clear below to force a fresh API call.'=>'ذاكرة التخزين المؤقت للترجمات التي يتم إنشاؤها بواسطة الذكاء الاصطناعي، والوصف التعريفي، والمقتطفات، والمحتوى. نشطة دائمًا — لا حاجة لمفتاح تبديل منفصل. يتم إبطال الإدخالات تلقائيًا عند تغيير المحتوى أو مزود/نموذج الذكاء الاصطناعي. استخدم زر "↺ إعادة الترجمة" في شريط الأدوات أو انقر على مسح أدناه لفرض استدعاء API جديد.','Permalink rules flushed successfully.'=>'تم تفريغ قواعد الرابط الدائم بنجاح.','Permission denied.'=>'تم رفض الإذن.','Persuasive'=>'إقناعي','PHP constant'=>'ثابت PHP','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'تثبيت المصطلحات التي يجب عدم ترجمتها أو التي يجب دائمًا عرضها بطريقة معينة (مثل أسماء العلامات التجارية، أسماء المنتجات، الاختصارات). يتم حقن قيود القاموس في كل طلب ترجمة للذكاء الاصطناعي لجميع الميزات: ترجمة المنشور، الوصف التعريفي، المقتطف، وترجمة قالب FSE.','Plain language'=>'لغة بسيطة','Please enter some instructions first…'=>'يرجى إدخال بعض التعليمات أولاً…','Please enter some text first…'=>'يرجى إدخال بعض النصوص أولاً…','Post'=>'منشور','Post not found.'=>'المنشور غير موجود.','Post Types'=>'أنواع المنشورات','Prefilled from excerpt. Edit to override.'=>'مملوء مسبقًا من المقتطف. عدل للتجاوز.','Primary Language'=>'اللغة الأساسية','Primary language'=>'اللغة الأساسية','Primary language saved.'=>'تم حفظ اللغة الأساسية.','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'اللغة الأساسية: اللغة التي كتب بها المحتوى الحالي الخاص بك. يتم إنتاج جميع الترجمات من هذه اللغة؛ تغييرها لا ينقل أو يحذف أي منشورات.','Processing…'=>'جار المعالجة…','Provider'=>'المزود','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'لم يُرجع المزود نصًا. تحقق من سجل أخطاء ووردبريس لمعرفة سبب الفشل بالتفصيل.','Quality'=>'جودة','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'الجودة (افتراضي — Sonnet / GPT-4o / Gemini Pro)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'الجودة (سونيت / GPT-4o / جمنى برو)','Quality: used for post translation and content generation — higher quality, higher cost.'=>'الجودة: تستخدم لترجمة المنشورات وتوليد المحتوى — جودة أعلى، تكلفة أعلى.','Quick Translate'=>'ترجمة سريعة','Quick Translation'=>'ترجمة سريعة','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'تُستخدم الترجمة السريعة في وضع المقتطف / القطعة — ترجمات قصيرة يتم طلبها عند الحاجة من شريط الأدوات أو المحرر أو نوافذ النقر على الكتل. تستخدم تكوينًا منفصلًا وأخف من ترجمة الصفحة الكاملة للحفاظ على سرعة الاستجابة وتقليل التكاليف.','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'يعيد تفعيل canLockBlocks الخاص بـ Gutenberg. مفيد لنماذج التحرير التي تحتاج إلى منع المساهمين من نقل أو حذف كتل معينة.','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'يعيد تفعيل supportsTemplateMode. أساسي لعمليات تحرير الموقع الكامل حيث تكون تجاوزات النموذج على مستوى المنشور مقصودة.','Re-generates and updates the cached result.'=>'يعيد التوليد ويحدث النتيجة المخزنة مؤقتًا.','Re-scan'=>'إعادة الفحص','Re-scanning…'=>'إعادة الفحص…','Re-translate'=>'إعادة الترجمة','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'إعادة توجيه الزوار إلى لغتهم المفضلة استنادًا إلى رأس Accept-Language الخاص بالمتصفح','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'تحسين أكثر — مثلاً "اجعله أقصر" أو "استخدم نغمة رسمية"…','Refine further:'=>'تحسين أكثر:','Refinement'=>'تحسين','Refinement failed — please try again.'=>'فشل التَّحسين — يرجى المحاولة مرة أخرى.','Refining…'=>'جارٍ التَّحسين…','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'يعيد إنشاء قواعد إعادة كتابة ووردبريس بحيث تكون بادئات URL، والكلمات المفتاحية الخاصة باللغة، وإعادة كتابة الأرشيف متزامنة. ضروري بعد تغيير اللغة الأساسية أو إضافة دعم لغة جديدة.','Remove stored key'=>'إزالة المفتاح المخزن','Report an issue on GitHub'=>'الإبلاغ عن مشكلة على GitHub','Request failed — please try again.'=>'فشل الطلب — يرجى المحاولة مرة أخرى.','Request failed.'=>'فشل الطلب.','Request failed. Check your connection.'=>'فشلت الطلب. تحقق من اتصالك.','Request failed. Please try again.'=>'فشلت الطلب. يرجى المحاولة مرة أخرى.','Requests'=>'الطلبات','Reset'=>'إعادة تعيين','Result will appear here…'=>'سيظهر النتيجة هنا…','Retranslate'=>'إعادة الترجمة','Retranslating…'=>'جارٍ إعادة الترجمة…','Review carefully — links and slugs not updated.'=>'راجع بعناية — لم يتم تحديث الروابط والروابط المختصرة.','Review translation before applying'=>'مراجعة الترجمة قبل التطبيق','Revise'=>'راجع','Revision'=>'مراجعة','Revision Type'=>'نوع المراجعة','Router'=>'الموجه','Router Tab'=>'علامة التبويب الموجه','Save Debug Setting'=>'حفظ إعداد التصحيح','Save Router Settings'=>'حفظ إعدادات الموجه','Save Settings'=>'حفظ الإعدادات','Save the post to persist changes.'=>'احفظ المنشور للحفاظ على التغييرات.','Save Uninstall Setting'=>'حفظ إعداد إلغاء التثبيت','Saved to the meta description field when you apply.'=>'تم حفظه في حقل وصف الميتا عند التطبيق.','Scan failed: '=>'فشل الفحص: ','Scan request failed. Please try again.'=>'فشل طلب الفحص. يرجى المحاولة مرة أخرى.','Scanning posts for broken language links…'=>'فحص المنشورات للروابط المكسورة…','Search'=>'بحث','Search Results'=>'نتائج البحث','Security check failed — file path is not permitted.'=>'فشل التحقق الأمني — مسار الملف غير مسموح به.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'اختر لغة لإدارة قوالب FSE الخاصة بها، وأجزاء القالب، وقوائم التنقل.','Select language'=>'اختر اللغة','SEO character-count info'=>'معلومات عدد الأحرف لتحسين محركات البحث','Server setup (subdomain)'=>'إعداد الخادم (النطاق الفرعي)','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'يحدد السلوك الافتراضي للذكاء الاصطناعي لجميع الميزات على مستوى الموقع. يمكن للمنشورات الفردية تجاوز ذلك لخاصية الترجمة وتوليد المحتوى عبر مربع بيانات Lingua Forge.','Settings'=>'الإعدادات','Settings saved.'=>'تم حفظ الإعدادات.','Show home link'=>'عرض رابط الصفحة الرئيسية','Shown when no translation exists for the visitor\'s language.'=>'تظهر عندما لا توجد ترجمة للغة الزائر.','Single'=>'مفرد','Single %s'=>'فرد %s','Single: %s'=>'فرد: %s','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'السقف على مستوى الموقع لطلبات الذكاء الاصطناعي لكل يوم بالتوقيت العالمي المنسق (يشمل ترجمات شريط الأدوات ومراجعات الكتل). يعاد تعيين العداد عند منتصف الليل بالتوقيت العالمي المنسق. اضبطه على 0 لتعطيل الحد.','Size'=>'الحجم','Some link fixes failed.'=>'فشلت بعض إصلاحات الروابط.','Some nav ref fixes failed.'=>'فشلت بعض إصلاحات مراجع التنقل.','Some part fixes failed.'=>'فشلت بعض إصلاحات الأجزاء.','Some parts could not be created.'=>'تعذر إنشاء بعض الأجزاء.','Some templates could not be created.'=>'تعذر إنشاء بعض القوالب.','Some translations failed.'=>'فشلت بعض الترجمات.','Source file not found.'=>'لم يتم العثور على الملف المصدر.','Source lang'=>'اللغة المصدر','Source language'=>'اللغة المصدر','Source term'=>'المصطلح المصدر','Standard'=>'افتراضي','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'يستخدم الوضع القياسي درجة حرارة مخصصة لكل ميزة: الترجمة T=0.2 (دقيق)، الترجمة السريعة T=0.4، مولد المحتوى T=0.6 (مبدع). تطبق الإعدادات المسبقة الأخرى درجة حرارة ثابتة واحدة عبر جميع الميزات.','Status'=>'الحالة','Status / Actions'=>'الحالة / الإجراءات','Storytelling'=>'سرد القصص','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'وضع الحفظ الصارم للمحتوى القانوني والتنظيمي والطبي أو التقني. عند التفعيل، يستخدم كل ميزة ذكاء اصطناعي درجة حرارة عينة منخفضة ويضيف الملحق أدناه إلى مطالبه النظامية — يتم الحفاظ على المصطلحات وأرقام المقالات والوحدات وأسماء العلامات التجارية واللغة التنظيمية حرفيًا بدلاً من إعادة صياغتها.','Structured Outline'=>'مخطط منظم','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'يتطلب وضع النطاق الفرعي أن يشير خادم الويب الخاص بك إلى جميع النطاقات الفرعية للغة (مثل de.example.com) إلى تثبيت ووردبريس هذا. بعد تغيير الأوضاع، قم بمسح قواعد الروابط الثابتة وامسح أي ذاكرات مؤقتة. إذا كان عنوان URL الرئيسي الخاص بك يتضمن www (مثل www.example.com)، استخدم مرشح lf_base_domain لضبط النطاق الأساسي الخالي بحيث يتم إنشاء النطاقات الفرعية بشكل صحيح.','Subdomain — de.example.com/'=>'النطاق الفرعي — de.example.com/','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Only one provider is active at a time. Select the active provider on the General tab.'=>'مزودو الدعم: Anthropic (Claude)، OpenAI (GPT)، Google (Gemini). مزود واحد فقط نشط في وقت واحد. اختر المزود النشط في علامة التبويب العامة.','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6، لكل ميزة','Target lang'=>'اللغة الهدف','Target Language'=>'اللغة المستهدفة','Target language'=>'اللغة الهدف','Target term'=>'المصطلح الهدف','Target: 140–160 chars for optimal SERP display'=>'الهدف: 140–160 حرفًا لعرض مثالي في نتائج البحث','Technical'=>'تقني','Technical / Scientific'=>'تقني / علمي','Technical / Scientific instructions'=>'تعليمات تقنية / علمية','Template "%s" already exists.'=>'القالب "%s" موجود بالفعل.','Template "{expected}" does not exist — create it in the Site Editor first.'=>'القالب "{expected}" غير موجود — أنشئه في محرر الموقع أولاً.','Template has no content.'=>'القالب لا يحتوي على محتوى.','Template mode'=>'وضع النموذج','Template not found or not stored in the database.'=>'القالب غير موجود أو غير مخزن في قاعدة البيانات.','Template part "%s" already exists.'=>'جزء القالب "%s" موجود بالفعل.','Template part has no content.'=>'جزء القالب لا يحتوي على محتوى.','Template part not found or not stored in the database.'=>'جزء القالب غير موجود أو غير مخزن في قاعدة البيانات.','Template Parts'=>'أجزاء القالب','Templates'=>'القوالب','Test connection'=>'اختبار الاتصال','Testing…'=>'جارٍ الاختبار…','Text domain / locale'=>'نطاق النص / اللغة','Text to translate'=>'النص المراد ترجمته','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Subsequent requests with identical inputs are served from the cache with no API call. The cache is different from Translation Memory: Translation Memory operates at the block level and is shared across posts; the API Response Cache operates at the feature level and is keyed per post.'=>'ذاكرة التخزين المؤقت لاستجابة API تخزن النتيجة الخام لكل طلب ذكاء اصطناعي — ترجمة، وصف تعريفي، مقتطف، وتوليد المحتوى — بواسطة تجزئة المدخلات (المحتوى، زوج اللغة، المزود، النموذج). الطلبات اللاحقة ذات المدخلات المتطابقة تُقدم من الذاكرة المؤقتة بدون استدعاء API. تختلف الذاكرة المؤقتة عن ذاكرة الترجمة: تعمل ذاكرة الترجمة على مستوى الكتلة وتُشترك عبر المنشورات؛ تعمل ذاكرة استجابة API على مستوى الميزة وتُفهرس لكل منشور.','The editor did not accept the content — please try again.'=>'لم يقبل المحرر المحتوى — يرجى المحاولة مرة أخرى.','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'يستخدم مستوى الضوء النموذج السريع المكون في جدول النماذج أعلاه (افتراضي: هايكو / فلاش). قم بالتبديل إلى الجودة إذا كنت بحاجة إلى نفس دقة الترجمة كوضع الصفحة الكاملة للمقتطفات.','The phrase as it appears in the source text.'=>'العبارة كما تظهر في النص المصدر.','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'اللغة الأساسية دائمًا تُقدم في جذر موقعك — بدون بادئة URL في وضع المسار، بدون نطاق فرعي للغة في وضع النطاق الفرعي. تستخدم جميع اللغات الأخرى بادئة مسار /lang/ (مثل example.com/de/) أو نطاق فرعي للغة (مثل de.example.com)، اعتمادًا على إعداد بنية URL أدناه.','The source page has no footnotes.'=>'صفحة المصدر لا تحتوي على حواشي.','The upload failed — please try again.'=>'فشل التحميل — يرجى المحاولة مرة أخرى.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'هذه الحواشي تأتي من صفحة المصدر وتعرض هنا للمرجعية فقط. أضفها إلى هذه الصفحة باستخدام محرر الكتل.','This is the source page. Footnotes are edited directly in the block editor.'=>'هذه هي صفحة المصدر. يتم تحرير الحواشي مباشرة في محرر الكتل.','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'هذا المفتاح يتم تزويده حاليًا من قبل خادم %s ولا يمكن إزالته هنا. أدخل مفتاحًا جديدًا أعلاه لتجاوز ذلك بقيمة من قاعدة البيانات.','Tip: to reset a model to the built-in default, clear the field and save.'=>'نصيحة: لإعادة تعيين نموذج إلى الإعداد الافتراضي المدمج، امسح الحقل واحفظ.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'لاستخدام سر تشفير مخصص (بدلاً من قيمة wp_salt المستمدة)، أضف هذا إلى wp-config.php:','Today'=>'اليوم','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are deliberately excluded so they don\'t skew the totals. The underlying table aggregates daily — pick a window below to view it.'=>'استهلاك الرموز مجمع حسب الميزة، المزود، والنموذج. مسجل في كل مكالمة ذكاء اصطناعي ناجحة؛ يتم استبعاد اختبار الاتصال عمدًا حتى لا تؤثر على الإجماليات. الجدول الأساسي يجمع البيانات يوميًا — اختر نافذة أدناه لعرضها.','Tone'=>'نغمة','tone'=>'نغمة','Tone:'=>'نغمة:','Too many AI requests. Please retry in %d seconds.'=>'طلبات الذكاء الاصطناعي كثيرة جدًا. يرجى المحاولة مرة أخرى بعد %d ثوانٍ.','Total'=>'الإجمالي','Total tokens'=>'إجمالي الرموز','Translate'=>'ترجمة','Translate / Revise'=>'ترجمة / مراجعة','Translate / Revise block'=>'ترجمة / مراجعة الكتلة','Translate all'=>'ترجمة الكل','Translate chunk'=>'ترجمة الجزء','Translate Content'=>'ترجمة المحتوى','Translate missing'=>'الترجمة المفقودة','Translate page…'=>'ترجمة الصفحة…','Translated content'=>'المحتوى المترجم','Translated Names'=>'الأسماء المترجمة','Translated title'=>'العنوان المترجم','Translated to:'=>'مترجم إلى:','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'تمت الترجمة. راجع في محرر الموقع — الروابط الداخلية، روابط التنقل، واسم القوالب لا يتم تحديثها تلقائيًا.','Translating…'=>'جارٍ الترجمة…','Translation'=>'الترجمة','Translation Caching'=>'ذاكرة التخزين المؤقت للترجمة','Translation found but permalink could not be generated'=>'تم العثور على الترجمة ولكن لم يتم إنشاء الرابط الدائم','Translation Limits'=>'حدود الترجمة','Translation Limits & Behavior'=>'حدود وسلوك الترجمة','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'حدود الترجمة: تحكم في الأدوار التي يمكنها تفعيل الترجمة بالذكاء الاصطناعي، وتحدد ميزانية رموز شهرية. تجاوز الميزانية يُوقف استدعاءات الذكاء الاصطناعي حتى بداية الشهر الجديد.','Translation Memory'=>'ذاكرة الترجمة','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'ذاكرة الترجمة تخزن نتائج الذكاء الاصطناعي بواسطة تجزئة المحتوى، زوج اللغة، المزود، والنموذج. تحرير منشور يلغي صلاحية الإدخال في الذاكرة بحيث تحصل على نتيجة جديدة في المرة التالية.','Translation Memory cleared. %d cached block was removed.'=>'تم مسح ذاكرة الترجمة المؤقتة. تم حذف كتلة مخزنة واحدة.' . "\0" . 'تم مسح ذاكرة الترجمة المؤقتة. تم حذف %d كتل مخزنة.' . "\0" . '' . "\0" . '' . "\0" . '' . "\0" . '','Translation Memory: stores the full translated post per content hash. Clear it when you want to force a retranslation of all posts regardless of whether their content changed.'=>'ذاكرة الترجمة: تخزن النص المترجم بالكامل لكل تجزئة محتوى. امسحها عندما تريد فرض إعادة ترجمة لجميع المنشورات بغض النظر عما إذا كانت محتوياتها قد تغيرت.','Translation workflow'=>'سير عمل الترجمة','Translation, Content Generator'=>'الترجمة، مولد المحتوى','Type'=>'النوع','Uli Hake'=>'ولي هاك','Uninstall Behaviour'=>'إلغاء تثبيت السلوك','Uninstall setting saved.'=>'تم حفظ إعداد إلغاء التثبيت.','unknown error'=>'خطأ غير معروف','Unknown provider.'=>'مزود غير معروف.','Up'=>'أعلى','Upload .mo file'=>'تحميل ملف .mo','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'قم بتحميل ملفات .mo المجمعة لتجاوز سلاسل الإضافات الخارجية للغات المحددة — على سبيل المثال، ترجمة VikBooking مخصصة تستخدم "شقة" بدلاً من "غرفة". يجب أن تتبع الملفات نمط تسمية ووردبريس: {textdomain}-{locale}.mo (مثال: vikbooking-ca.mo). يتم تخزينها في مجلد التحميلات وتظل بعد تحديث الإضافة.','Upload Override'=>'تحميل التجاوز','URL could not be mapped to a post — check the link target exists'=>'تعذر ربط عنوان URL بمنشور — تحقق من وجود الهدف الرابط','URL structure'=>'بنية URL','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'هيكل URL: وضع بادئة المسار (example.com/de/) لا يتطلب تغييرات في الخادم. وضع النطاق الفرعي (de.example.com) يتطلب سجل DNS عام، وشهادة SSL عامة، وتغيير في إعدادات خادم الويب — راجع دليل إعداد الخادم.','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'استخدم علامات التبويب في أعلى هذه الصفحة لضبط كل منطقة. التغييرات على علامة التبويب الموجه تأخذ مفعولها فورًا؛ التغييرات على مفاتيح الذكاء الاصطناعي وإعدادات النموذج تنطبق على الطلب التالي.','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'جدول المصطلحات الذي يديره المستخدم لكل زوج لغة. يتم إرفاق الإدخالات بموجه نظام الترجمة بحيث يستخدم الذكاء الاصطناعي المصطلحات المفضلة بشكل متسق — وهو أمر حاسم لمفردات المجال ("kWp"، "PPA"، "نقطة الاتصال")، أسماء العلامات التجارية التي لا يجب ترجمتها، والعبارات التنظيمية الموحدة. كلا حقلَي اللغة اختياريان: اترك "اللغة المصدر" فارغة لتطبيق الإدخال بغض النظر عن اللغة التي تترجم منها؛ اترك "اللغة الهدف" فارغة لتطبيقه على جميع اللغات الهدف مرة واحدة.','Using custom meta description.'=>'استخدام وصف ميتا مخصص.','View'=>'عرض','View built-in default'=>'عرض الإعداد الافتراضي المدمج','View details'=>'عرض التفاصيل','View Lingua Forge details'=>'عرض تفاصيل لينغا فورج','Visit plugin site'=>'زيارة موقع الإضافة','Warning:'=>'تحذير:','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'عندما يتم تفعيل تسجيل التصحيح (عبر التبديل أدناه أو بتعريف LINGUAFORGE_AI_DEBUG في wp-config.php)، تكتب ميزات ترجمة القالب وترجمة الترجمة FSE مطالبات الذكاء الاصطناعي واستجاباتهما إلى القرص لأغراض استكشاف الأخطاء وإصلاحها. استخدم هذا القسم لمراقبة تلك المخرجات ومسحها بمجرد أن تحصل على ما تحتاجه — يمكن أن تنمو الملفات بسرعة على الصفحات الكبيرة. قم بتكوين دليل الوجهة عبر مرشح linguaforge_debug_dir.','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'عند التمكين، يتم إعادة توجيه الزائرين لأول مرة الذين لا يملكون كوكي لغة ولا يوجد بادئة لغة في عنوان URL إلى أقرب إصدار مطابق للغة. يتم تخطي إعادة التوجيه إذا لم تكن اللغة المفضلة للمتصفح من بين لغات الموجه النشطة. بمجرد أن يختار الزائر لغة عبر المبدل، تأخذ الكوكي الأولوية ويتم تجاهل رأس المتصفح في جميع الزيارات المستقبلية.','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'أي طبقة نموذج لاستخدامها للترجمة الكاملة للصفحة. الجودة تستخدم النموذج المكون في جدول النماذج أعلاه ويوصى بها للترجمة الدقيقة والطويلة. انتقل إلى الخفيف فقط إذا كانت السرعة أو التكلفة أولوية والمحتوى قصير.','WP-CLI reference'=>'مرجع WP-CLI','Write AI prompts and responses to disk for troubleshooting'=>'كتابة مطالبات واستجابات الذكاء الاصطناعي إلى القرص لأغراض استكشاف الأخطاء وإصلاحها','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'يمكنك أيضًا تعريف المفاتيح كثوابت أو متغيرات بيئة (على سبيل المثال في wp-config.php). تُستخدم هذه المصادر تلقائيًا كبديل عند عدم وجود مفتاح مخزن في قاعدة البيانات.','You do not have permission to manage these settings.'=>'ليس لديك إذن لإدارة هذه الإعدادات.','You do not have permission to read this post.'=>'ليس لديك إذن لقراءة هذا المنشور.','{n} stale path(s)'=>'{n} مسار قديم','— Any source language —'=>'— أي لغة مصدر —','— Any target language —'=>'— أي لغة هدف —','— Any target —'=>'— أي هدف —','— Any —'=>'— أي —','— auto-detect —'=>'— اكتشاف تلقائي —','— select a language —'=>'— اختر لغة —','— toggle in Settings → Behavior.'=>'— التبديل في الإعدادات → السلوك.','← Back'=>'← العودة','↑ Detected from current post'=>'↑ تم اكتشافه من المنشور الحالي','↺ Re-translate'=>'↺ إعادة الترجمة','↺ Refine'=>'↺ تحسين','↺ Refresh'=>'↺ تحديث','↺ Refreshing…'=>'↺ جارٍ التحديث…','⚠ Borderline'=>'⚠ على الحد الفاصل','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ لم يتم العثور على منشورات <strong>{lang}</strong>. تأكد من أن جميع المنشورات المترجمة تحتوي على متغير اللغة مضبوط على <strong>{lang}</strong> في مربع بيانات اللغة.','⚠ No changes'=>'⚠ لا تغييرات','⚠ No changes — re-scan?'=>'⚠ لا تغييرات — إعادة الفحص؟','✅ Fixed ({n})'=>'✅ تم الإصلاح ({n})','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ لم يتم العثور على روابط مكسورة أو تطابقات قالب خاطئة لـ <strong>{lang}</strong>. تم فحص <strong>{scanned}</strong> منشورًا و صفحة — جميع الفحوصات ناجحة. روابط أجزاء القالب (رأس الصفحة، تذييل الصفحة، الشريط الجانبي) غير مشمولة هنا — استخدم زر إصلاح أجزاء القالب لفحصها بشكل منفصل.','✅ Template fixed'=>'✅ تم إصلاح القالب','✓ All parts created.'=>'✓ تم إنشاء جميع الأجزاء.','✓ All templates created.'=>'✓ تم إنشاء جميع القوالب.','✓ All translated.'=>'✓ تم الترجمة جميعها.','✓ Configured'=>'✓ تم التكوين','✓ Connection OK'=>'✓ الاتصال جيد','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ تم إنشاء المحتوى — راجع، حسّن، وطبق من خلال التراكب.','✓ Done'=>'✓ تم','✓ Enabled'=>'✓ مفعّل','✓ Good length'=>'✓ طول جيد','✓ In safe storage'=>'✓ في التخزين الآمن','✓ Language installed.'=>'✓ تم تثبيت اللغة.','✓ Links fixed.'=>'✓ تم إصلاح الروابط.','✓ Nav refs fixed.'=>'✓ تم إصلاح مراجع التنقل.','✓ Parts fixed.'=>'✓ تم إصلاح الأجزاء.','✓ Pattern translated.'=>'✓ تم ترجمة النمط.','✓ Refined — review the updated draft above.'=>'✓ تم التَّحسين — راجع المسودة المحدثة أعلاه.','✓ Translation saved'=>'✓ تم حفظ الترجمة','✗ Disabled'=>'✗ معطل','✗ Error:'=>'✗ خطأ:','✗ Failed:'=>'✗ فشل:','✗ Not configured'=>'✗ غير مكون','✗ Too long'=>'✗ طويل جدًا','✗ Too short'=>'✗ قصير جدًا','❌ Failed'=>'❌ فشل','📄 Wrong template'=>'📄 قالب خاطئ','📍 Stale path (page moved)'=>'📍 مسار قديم (تم نقل الصفحة)']];
